  assert.equal(parseId(s), Number(s));
}
for (const s of ['0', '-0', '01', '001', '-1', '+1', '1x', ' 1', '1 ', '1\\n', '1\\r\\n', '', '1.0', '1.5', '1e3', '0x10', 'Infinity', 'NaN', '9007199254740992', '9007199254740993', '999999999999999999999999999999', '１', null, undefined, 1, 1n, true, {}, [], Symbol('1')]) {
  assert.equal(parseId(s), null);
}
console.log('Supplied checks, syntax check, and additional boundary/input checks passed.');
NODE"

